import chalk from "chalk";
import type { Command } from "commander";
import { markMutating } from "../command-annotations.js";
import {
  AlignmentIndex,
  addProjectLevelTraitItem,
  addChildItem,
  type BulkPatchResult,
  buildIndexes,
  checkSlugUniqueness,
  createNote,
  createSpecItem,
  deleteSpecItem,
  findChildItems,
  findDescendantItems,
  findTraitImplementors,
  initContext,
  type LoadedSpecItem,
  loadAllItems,
  loadMetaContext,
  loadAllTasks,
  type PatchOperation,
  patchSpecItems,
  ReferenceIndex,
  resolveMetaRef,
  shortestUniqueUlid,
  updateSpecItem,
} from "../../parser/index.js";
import type { ItemFilter } from "../../parser/items.js";
import { commitIfShadow } from "../../parser/shadow.js";
import type {
  AcceptanceCriterion,
  ImplementationStatus,
  ItemType,
  Maturity,
  SpecItemInput,
} from "../../schema/index.js";
import { SpecItemPatchSchema } from "../../schema/index.js";
import {
  ImplementationStatusSchema,
  MaturitySchema,
} from "../../schema/common.js";
import { errors } from "../../strings/errors.js";
import { fieldLabels, sectionHeaders } from "../../strings/labels.js";
import { formatMatchedFields, grepItem } from "../../utils/grep.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, isJsonMode, output, success, warn } from "../output.js";
import { parseTagsArray } from "../parse-utils.js";

/**
 * Format a spec item for display
 */
function formatItem(
  item: LoadedSpecItem,
  refIndex: ReferenceIndex,
  verbose = false,
  grepPattern?: string,
): string {
  const shortId = refIndex.shortUlid(item._ulid);
  const slugStr = item.slugs.length > 0 ? chalk.cyan(`@${item.slugs[0]}`) : "";
  const typeStr = chalk.gray(`[${item.type}]`);

  let status = "";
  if (item.status && typeof item.status === "object") {
    const s = item.status as { maturity?: string; implementation?: string };
    if (s.implementation) {
      const implColor =
        s.implementation === "verified"
          ? chalk.green
          : s.implementation === "implemented"
            ? chalk.cyan
            : s.implementation === "in_progress"
              ? chalk.yellow
              : chalk.gray;
      status = implColor(s.implementation);
    } else if (s.maturity) {
      status = chalk.gray(s.maturity);
    }
  }

