          ...(isRootAdd
            ? {
                _sourceFile: ctx.manifestPath!,
                _path: addResult.path,
              }
            : {}),
        } as LoadedSpecItem;

        // Build index including the new item for accurate short ULID
        const index = new ReferenceIndex(
          [],
          [...items, resultItem],
