        const itemSlug = resultItem.slugs?.[0] || index.shortUlid(resultItem._ulid);
        const itemRef = `@${itemSlug}`;
        await commitIfShadow(ctx.shadow, "item-add", itemSlug);
        success(
          isRootAdd
